set-variable.value:
@{
        var source = (string)context.Variables["byokCredentialSource"];
        if (source == "jwt-bearer") { return context.Request.Headers["Authorization"][0].Substring(7).Trim(); }
        if (source == "jwt-header") { return context.Request.Headers[(string)context.Variables["byokCredentialHeader"]][0]; }
        return "";
      }

@{
        try {
          var value = (string)context.Variables["byokJwtToken"];
          if (value.Length > 32768 || !System.Text.RegularExpressions.Regex.IsMatch(value, @"\A[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\z")) { return false; }
          var parts = value.Split('.');
          for (var partIndex = 0; partIndex < 2; partIndex++) {
            var encoded = parts[partIndex].Replace('-', '+').Replace('_', '/');
            encoded = encoded.PadRight(encoded.Length + (4 - encoded.Length % 4) % 4, '=');
            var bytes = Convert.FromBase64String(encoded);
            var json = System.Text.Encoding.UTF8.GetString(bytes);
            if (!bytes.SequenceEqual(System.Text.Encoding.UTF8.GetBytes(json))) { return false; }
            var parsed = Newtonsoft.Json.Linq.JObject.Parse(json);
            var stringPattern = @"""(?:\\(?:[""\\/bfnrt]|u[0-9a-fA-F]{4})|[^""\\\u0000-\u001F])*""";
            var withoutStrings = System.Text.RegularExpressions.Regex.Replace(json, stringPattern, "");
            if (System.Text.RegularExpressions.Regex.IsMatch(withoutStrings, @"[^{}\[\]:,\x20\x09\x0A\x0D0-9.eE+\-truefalsn]")) { return false; }
            var sourceProperties = 0;
            foreach (System.Text.RegularExpressions.Match item in System.Text.RegularExpressions.Regex.Matches(json, stringPattern)) {
              if (System.Text.RegularExpressions.Regex.IsMatch(json.Substring(item.Index + item.Length), @"\A\s*:")) { sourceProperties++; }
            }
            if (sourceProperties != withoutStrings.Count(character => character == ':')
                || sourceProperties != parsed.Descendants().OfType<Newtonsoft.Json.Linq.JProperty>().Count()) { return false; }
            if (partIndex == 1) {
              foreach (var name in new[] { "iss", "aud" }) {
                if (parsed[name] == null || parsed[name].Type != Newtonsoft.Json.Linq.JTokenType.String) { return false; }
              }
              foreach (var name in new[] { "tid", "oid", "azp", "sub", "uid", "cid", "idtyp" }) {
                if (parsed[name] != null && parsed[name].Type != Newtonsoft.Json.Linq.JTokenType.String) { return false; }
              }
              if (parsed["exp"] == null || parsed["exp"].Type != Newtonsoft.Json.Linq.JTokenType.Integer
                  || (parsed["nbf"] != null && parsed["nbf"].Type != Newtonsoft.Json.Linq.JTokenType.Integer)) { return false; }
              var scope = parsed["scp"];
              if (scope == null || (scope.Type != Newtonsoft.Json.Linq.JTokenType.String && scope.Type != Newtonsoft.Json.Linq.JTokenType.Array)
                  || (scope.Type == Newtonsoft.Json.Linq.JTokenType.Array && scope.Any(entry => entry.Type != Newtonsoft.Json.Linq.JTokenType.String))) { return false; }
                if (((string)parsed["iss"] == "{{caller-entra-issuer}}" && scope.Type != Newtonsoft.Json.Linq.JTokenType.String)
                  || ((string)parsed["iss"] == "{{caller-okta-issuer}}" && scope.Type != Newtonsoft.Json.Linq.JTokenType.Array)) { return false; }
            }
          }
          return true;
        } catch { return false; }
      }

@{
        try {
          if (!(bool)context.Variables["byokJwtShapeValid"]) { return "invalid"; }
          var value = (string)context.Variables["byokJwtToken"];
          var token = value.AsJwt();
          if (token == null || token.Algorithm != "RS256" || !token.Claims.ContainsKey("iss")
              || token.Claims["iss"] == null || token.Claims["iss"].Length != 1
              || token.Claims["iss"][0] != token.Issuer) { return "invalid"; }
          var entra = "{{caller-entra-enabled}}" == "true" && token.Issuer == "{{caller-entra-issuer}}";
          var okta = "{{caller-okta-enabled}}" == "true" && token.Issuer == "{{caller-okta-issuer}}";
          if (entra == okta) { return "invalid"; }
          return entra ? "entra" : "okta";
        } catch { return "invalid"; }
      }

@{
    var method = (string)context.Variables["callerAuthMethod"];
    var issuer = (string)context.Variables["callerIssuer"];
    var subject = (string)context.Variables["callerSubject"];
    if (string.IsNullOrWhiteSpace(issuer) || string.IsNullOrWhiteSpace(subject)) { return ""; }
    if (method == "subscriptionKey") {
      if (context.Subscription == null || subject != context.Subscription.Id || issuer != "apim") { return ""; }
    } else if ((method != "entraJwt" && method != "oktaJwt") || !(bool)context.Variables["byokJwtValidated"]) { return ""; }
    return method + ":" + issuer.Length.ToString() + ":" + issuer + ":" + subject;
  }
